WITH unpacked AS (SELECT id, host, log_ts, latency_ms, context, context['trace'] AS trace, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, context['region'] AS region FROM app_logs) SELECT id, log_ts, tier, AVG(latency_ms) OVER (PARTITION BY host, tier ORDER BY log_ts, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS latency_ms_avg_3, LAST_VALUE(tier) IGNORE NULLS OVER (PARTITION BY host, tier ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_tier, SUM(latency_ms) OVER (PARTITION BY host ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_latency_ms, LEAD(latency_ms, 2, 0) OVER (PARTITION BY tier ORDER BY latency_ms, id) AS next_latency_ms FROM unpacked;
